int send_diseqc_message(struct dvb_frontend *fe, struct dvb_diseqc_master_cmd *d) {
    int ret = 0;
    int i = 0;

    if (!fe || !d) {
        return -EINVAL;
    }

    if (d->msg[0] < 0x01 || d->msg[0] > 0x04) {
        return -EINVAL;
    }

    if (d->msg_len < 1 || d->msg_len > DVB_MAX_DISEQC_MSG_LEN) {
        return -EINVAL;
    }

    for (i = 0; i < d->msg_len; i++) {
        if (d->msg[i] < 0x00 || d->msg[i] > 0xff) {
            return -EINVAL;
        }
    }

    d->msg_len = i;

    if (d->msg[0] == 0x01 || d->msg[0] == 0x03) {
        d->tx_tone = 1;
    } else {
        d->tx_tone = 0;
    }

    ret = fe->ops.send_diseqc_msg(fe, d);
    if (ret < 0) {
        return ret;
    }

    for (i = 0; i < 100; i++) {
        if (fe->ops.is_diseqc_msg_sent(fe)) {
            break;
        }
        usleep(10000);
    }

    if (i == 100) {
        return -ETIMEDOUT;
    }

    return 0;
}
